/** Ansage vor der Folge ("Wiederhole:"), je Sprache. */
export const LEAD_MS = {
  "de": {
    "word": "Wiederhole:",
    "ms": 810
  },
  "ru": {
    "word": "Повтори:",
    "ms": 836
  }
};
export const LEAD_MP3 = {
"de": "",
"ru": ""
};

/** Ist die Sprache vorhanden? */
export function hasDigits(lang) {
  return Object.prototype.hasOwnProperty.call(DIGIT_MP3, lang);
}
